    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Xhq12 order;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Xpj42 sale;


    @Builder.Default
    @Column(nullable = false)
    private boolean isInstantPurchase = false;







    public void assignOrder(Xhq12 order) {

        if (this.order != null && this.order != order) {
            Xhq12 oldOrder = this.order;
            this.order = null;
            if (oldOrder.getOrderBid() == this) {
                oldOrder.assignOrderBid(null);
            }
        }


        this.order = order;


        if (order != null) {
            this.status = Xkh73Status.MATCHED;


            if (order.getOrderBid() != this) {
                order.assignOrderBid(this);
            }
        }
    }






    public void assignSale(Xpj42 sale) {
        this.sale = sale;
        this.status = Xkh73Status.MATCHED;
    }




    public void markAsInstantPurchase() {
        this.isInstantPurchase = true;
    }






    public void updateStatus(Xkh73Status newStatus) {
        this.status = newStatus;
    }
}

    private Xzt63 getSaleBidAndValidate(Long saleBidId) {
        Xzt63 saleBid = saleBidQueryService.findById(saleBidId);
        if (saleBid == null) {
            throw new Xbk76Exception("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
        }

        Xpj42 sale = saleBid.getSale();
        if (sale == null) {
            throw new Xzj75Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
        }

        return saleBid;
    }




    private Xtw92 createInstantOrderBid(Xhq12 order, Xzt63 saleBid, Xpj42 sale) {
        Xcc44 productSize = saleBid.getProductSize();

        Xtw92 orderBid = Xtw92.builder()
                .user(order.getUser())
                .productSize(productSize)
                .bidPrice(saleBid.getBidPrice())
                .status(Xkh73Status.MATCHED)
                .order(order)
                .sale(sale)
                .build();


        orderBid.assignOrder(order);


        orderBid.markAsInstantPurchase();
        return orderBidRepository.save(orderBid);
    }




    private void handleOrderBidCreationException(Exception e, String operation) {
        if (e instanceof Xhq12Exception) {
            throw (Xhq12Exception) e;
        }
